  }
 ],
 "actions": [
  {
   "title": "C 栋主机清洗与群控调优",
   "text": "11 月第二周完成冷凝器清洗，群控策略改为按负荷台数调节，预计节电 6%。",
   "owner": "机电组"
  },
  {
   "title": "错峰运行储能与蓄冷",
   "text": "高温日 13:00–16:00 释放储能，夜间蓄冷，目标峰时占比降至 40% 以下。",
   "owner": "能源管理部"
  },
  {
   "title": "数据中心 PUE 冲刺 1.40",
   "text": "冷通道封闭剩余 4 列机柜，提高送风温度 1℃。",
   "owner": "数据中心运维"
  }
 ],
 "risks": [
  {
   "title": "冬季供暖切换",
   "text": "11 月中旬切换供暖，C 栋主机若未调优，能耗可能再升 5% 以上。"
  },
  {
   "title": "需量电费",
   "text": "若再超预警线一次，本季度需量电费将增加约 3.2 万元。"
  }
 ],
